import type {
  ProviderBCommitBatch,
  ProviderBReservationRow,
  ProviderBStorage,
  ProviderBStockRow,
  Reservation,
  Service,
  ServiceResponse,
  Stock,
} from "./types";
import { error } from "./reservation";
import { decimalText, isId, isQuantity, isRecord, isRevision, isUnits, parseDecimalText } from "./validation";

type Command =
  | { op: "getAvailability"; sku: string }
  | { op: "getReservation"; reservationId: string }
  | { op: "reserve"; reservationId: string; sku: string; quantity: number };

type ReadResult =
  | { kind: "found"; value: unknown }
  | { kind: "missing" }
  | { kind: "unavailable" };

function parseCommand(raw: unknown): Command | undefined {
  if (!isRecord(raw)) return undefined;
  switch (raw.op) {
    case "getAvailability":
      return isId(raw.sku) ? { op: raw.op, sku: raw.sku } : undefined;
    case "getReservation":
      return isId(raw.reservationId)
        ? { op: raw.op, reservationId: raw.reservationId } : undefined;
    case "reserve":
      return isId(raw.reservationId) && isId(raw.sku) && isQuantity(raw.quantity)
        ? { op: raw.op, reservationId: raw.reservationId, sku: raw.sku, quantity: raw.quantity }
        : undefined;
    default:
      return undefined;
  }
}

function reservationResponse(status: 200 | 201, reservation: Reservation): ServiceResponse {
  return {
    status,
    body: {
      reservationId: reservation.reservationId,
      sku: reservation.sku,
      quantity: reservation.quantity,
    },
  };
}

async function readProviderB(
  storage: ProviderBStorage,
  collection: "inventory" | "reservations",
  key: string,
): Promise<ReadResult> {
  try {
    const envelope = await storage.read({ collection, key });
    if (!isRecord(envelope) || typeof envelope.ok !== "boolean") return { kind: "unavailable" };
    if (envelope.ok) {
      return "value" in envelope && envelope.value !== undefined && envelope.value !== null
        ? { kind: "found", value: envelope.value }
        : { kind: "unavailable" };
    }
    if (!isRecord(envelope.error) || typeof envelope.error.reason !== "string") {
      return { kind: "unavailable" };
    }
    return envelope.error.reason === "NO_SUCH_KEY" ? { kind: "missing" } : { kind: "unavailable" };
  } catch {
    return { kind: "unavailable" };
  }
}

function decodeStockRow(value: unknown, key: string): Stock | undefined {
  if (!isRecord(value) || value.itemKey !== key) return undefined;
  const totalUnits = parseDecimalText(value.onHandText);
  const reservedUnits = parseDecimalText(value.heldText);
  const revision = parseDecimalText(value.revisionText);
  if (totalUnits === undefined || reservedUnits === undefined || revision === undefined ||
      !isRevision(revision) || !isUnits(totalUnits) || !isUnits(reservedUnits) ||
      reservedUnits > totalUnits) {
    return undefined;
  }
  return { sku: value.itemKey, totalUnits, reservedUnits, revision };
}

function decodeReservationRow(value: unknown, key: string): Reservation | undefined {
  if (!isRecord(value) || value.bookingKey !== key || !isId(value.itemKey)) return undefined;
  const quantity = parseDecimalText(value.unitsText);
  if (quantity === undefined || !isQuantity(quantity)) return undefined;
  return { reservationId: value.bookingKey, sku: value.itemKey, quantity };
}

function stockRow(stock: Stock): ProviderBStockRow {
  return {
    itemKey: stock.sku,
    onHandText: decimalText(stock.totalUnits),
    heldText: decimalText(stock.reservedUnits),
    revisionText: decimalText(stock.revision),
  };
}

function reservationRow(reservation: Reservation): ProviderBReservationRow {
  return {
    bookingKey: reservation.reservationId,
    itemKey: reservation.sku,
    unitsText: decimalText(reservation.quantity),
  };
}

function commitBatch(previous: Stock, nextStock: Stock, reservation: Reservation): ProviderBCommitBatch {
  return {
    expectedRevisionText: decimalText(previous.revision),
    stockRow: stockRow(nextStock),
    reservationRow: reservationRow(reservation),
    outboxRows: [{
      key: "reservation.created:" + reservation.reservationId,
      category: "reservation",
      name: "created",
      payload: {
        bookingKey: reservation.reservationId,
        itemKey: reservation.sku,
        unitsText: decimalText(reservation.quantity),
      },
    }],
  };
}

export function createProviderBReservationService({ storage }: { storage: ProviderBStorage }): Service {
  return {
    async handle(raw): Promise<ServiceResponse> {
      const command = parseCommand(raw);
      if (command === undefined) return error(400, "invalid_command");

      if (command.op === "getAvailability") {
        const result = await readProviderB(storage, "inventory", command.sku);
        if (result.kind === "missing") return error(404, "stock_not_found");
        if (result.kind === "unavailable") return error(500, "storage_unavailable");
        const stock = decodeStockRow(result.value, command.sku);
        if (stock === undefined) return error(500, "storage_unavailable");
        return {
          status: 200,
          body: {
            sku: stock.sku,
            totalUnits: stock.totalUnits,
            reservedUnits: stock.reservedUnits,
            availableUnits: stock.totalUnits - stock.reservedUnits,
          },
        };
      }

      const reservationResult = await readProviderB(storage, "reservations", command.reservationId);
      if (reservationResult.kind === "unavailable") return error(500, "storage_unavailable");
      const existing = reservationResult.kind === "found"
        ? decodeReservationRow(reservationResult.value, command.reservationId)
        : undefined;
      if (reservationResult.kind === "found" && existing === undefined) {
        return error(500, "storage_unavailable");
      }
      if (command.op === "getReservation") {
        return existing ? reservationResponse(200, existing) : error(404, "reservation_not_found");
      }
      if (existing) {
        return existing.sku === command.sku && existing.quantity === command.quantity
          ? reservationResponse(200, existing)
          : error(409, "reservation_conflict");
      }

      const stockResult = await readProviderB(storage, "inventory", command.sku);
      if (stockResult.kind === "missing") return error(404, "stock_not_found");
      if (stockResult.kind === "unavailable") return error(500, "storage_unavailable");
      const stock = decodeStockRow(stockResult.value, command.sku);
      if (stock === undefined) return error(500, "storage_unavailable");
      if (stock.totalUnits - stock.reservedUnits < command.quantity) {
        return error(409, "insufficient_stock");
      }
      const nextRevision = stock.revision + 1;
      if (!isRevision(nextRevision)) return error(500, "storage_unavailable");
      const reservation: Reservation = {
        reservationId: command.reservationId,
        sku: command.sku,
        quantity: command.quantity,
      };
      try {
        const outcome = await storage.commitBatch(commitBatch(stock, {
          ...stock,
          reservedUnits: stock.reservedUnits + command.quantity,
          revision: nextRevision,
        }, reservation));
        if (outcome === "revision_conflict") return error(409, "commit_conflict");
        if (outcome !== "applied") return error(500, "storage_unavailable");
        return reservationResponse(201, reservation);
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

